 if(action==='like'){if(!requireUser())return;const p=storage.getFeed().find(p=>p.id===arg);feedLikedHere.add(arg);seenHistory.mark(arg);const saved=storage.toggleLike(arg,user.handle,p.author);render();await saved;}
