 if(kind==='login'){const handle=cleanHandle(data.handle),u=await storage.getUser(handle);if(!u||u.passwordHash!==await hash(handle+':'+data.password))throw Error('Kullanıcı adı veya şifre yanlış.');if(realtime.enabled)await bindAccount(handle,data.password);await setSession(u,!!data.remember);await rememberLogin(u,data.password,!!data.saveAccount);form.reset();render();return;}
 if(kind==='register'){const handle=cleanHandle(data.handle);if(handle.length<4||npcs.some(n=>n.kullanici_adi===canonicalHandle(handle)))throw Error('En az 3 harfli, kullanılmayan bir kullanıcı adı seç.');if(!safeText(data.name+' '+data.bio)||world.restrictedSystems.includes(data.system))throw Error('Profil bilgilerini ve sistemi kontrol et.');const u={id:handle.slice(1),handle,name:data.name.trim(),race:data.race,system:data.system,job:data.job.trim(),bio:data.bio.trim(),avatar:profileImage,coverColor:'#75dbe7',passwordHash:await hash(handle+':'+data.password),createdAt:Date.now()};await storage.saveUser(u,true);if(realtime.enabled)await bindAccount(handle,data.password);await setSession(u,!!data.remember);await rememberLogin(u,data.password,!!data.saveAccount);profileImage='';form.reset();render();return;}
 if(kind==='profile'){if(!user)return;if(!safeText(data.name+' '+data.bio)||world.restrictedSystems.includes(data.system))throw Error('Profil bilgilerini kontrol et.');const u={...user,name:data.name.trim(),race:data.race,system:data.system,job:data.job.trim(),bio:data.bio.trim(),coverColor:data.coverColor,bannerImage:bannerImage??user.bannerImage??'',avatar:profileImage||user.avatar||''};await storage.saveUser(u);user=u;modal=null;form.reset();render();toast('Profilin güncellendi.');return;}
 if(kind==='post'){if(!requireUser()||imageLoading)return;const sent=await storage.addPost({author:user.handle,text:data.text.trim(),system:user.system,race:user.race,...(composerImage?{image:composerImage}:{})});void realtime.react('posts',sent.id);composerImage='';form.reset();render();toast('Sesin ağa ulaştı.');return;}
 if(kind==='comment'){if(!requireUser())return;const p=storage.getFeed().find(p=>p.id===form.dataset.post);const sent=await storage.addComment({author:user.handle,text:data.text.trim(),postId:p.id,parentId:form.dataset.parent||null,recipient:form.dataset.parent?storage.list('comments').find(c=>c.id===form.dataset.parent)?.author:p.author,system:user.system,race:user.race});void realtime.react('comments',sent.id);form.reset();if(modal)delete modal.reply;render();return;}
