 if(kind==='npc-mute'){if(!dmUnlocked())return;const muted=storage.settings.muted,handle=data.handle;await storage.saveSettings({muted:muted.includes(handle)?muted.filter(h=>h!==handle):[...muted,handle]});toast('Ortak hesap tercihi kaydedildi.');render();return;}
 if(kind==='private-message'){if(!requireUser()||letterBusy)return;letterBusy=true;const peer=letterPeer;try{await realtime.send(peer,data.text.trim(),letterImage);letterImage='';form.reset();await refreshLetters();}finally{letterBusy=false;}render();return;}
 if(kind==='dm-login'){const digest=await hash('qorves-dm:'+data.password);if(storage.settings.dmHash&&storage.settings.dmHash!==digest)throw Error('DM şifresi yanlış.');if(!storage.settings.dmHash)await storage.saveSettings({dmHash:digest});sessionStorage.setItem('qorves-dm',digest);form.reset();render();return;}
 if(['settings','event','edit-event','dm-password'].includes(kind)&&!dmUnlocked())throw Error('Yönetim kilidi kapalı.');
 if(kind==='settings'){await storage.saveSettings({imageEnabled:!!data.imageEnabled,likesPerTurn:500,model:data.model.trim(),intervalMinutes:Number(data.intervalMinutes),maxRequests:Number(data.maxRequests),interactiveMaxRequests:Number(data.interactiveMaxRequests),maxPosts:Number(data.maxPosts),postsEnabled:!!data.postsEnabled,repliesEnabled:!!data.repliesEnabled});toast('Üretim ayarları kaydedildi.');}
