try{await storage.init({onProgress:boot.progress});const saved=JSON.parse(localStorage.getItem('qorves-session')||sessionStorage.getItem('qorves-session')||'null');if(saved&&!localStorage.getItem('qorves-account-changing')){const found=await storage.getUser(saved.handle);if(found?.passwordHash===saved.token){user=found;authOpen=false;await accountVault.profile(found).catch(()=>{});}}render();app.removeAttribute('aria-busy');await boot.complete();storage.subscribe(()=>{clearTimeout(renderTimer);renderTimer=setTimeout(()=>{scanNotices();render();},100);});setInterval(()=>{if(document.visibilityState==='visible'){void syncSeen();void refreshLetters();if(storage.settings.enabled){if(storage.usage.pending>0&&Date.now()-(storage.usage.lastScheduledWake||0)>900000&&Date.now()-lastPublishCheck>60000){lastPublishCheck=Date.now();void storage.flushDuePublications().catch(()=>{});}void realtime.tick();}}},5000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')void refreshLetters();});window.addEventListener('hashchange',()=>{void refreshLetters();});void refreshLetters();}catch(error){boot.fail();app.removeAttribute('aria-busy');app.innerHTML=`<div class="startup-error"><h1>Hat bağlantısı kurulamadı.</h1><p>${e(error.message)}</p><p>Küme hattına ulaşılamadı. Biraz sonra yeniden bağlanmayı dene.</p><button onclick="location.reload()">Yeniden bağlan</button></div>`;}






